// Curated learning content for every flag.
// f = distinctive visual characteristics (never names the country — safe to use as a hint)
// t = memory trick (an invented mnemonic, shown only in feedback / study views)
// s = documented symbolism (official or widely documented; omitted when not reliably documented)
// n = notes (recent changes, disputes, special cases)
export interface FlagContent {
  f: string;
  t: string;
  s?: string;
  n?: string;
}

export const CONTENT: Record<string, FlagContent> = {
  AFG: { f: 'Vertical black, red and green bands with a white emblem of a mosque framed by a wreath in the centre.', t: 'Black–red–green standing up with a white mosque: think "A for Arch" (the mihrab arch in the emblem).', s: 'Black recalls the troubled past, red the blood shed for independence, green hope and prosperity.', n: 'Shown as recognised at the United Nations. The Taliban-led administration uses a white flag bearing the black Shahada.' },
  AGO: { f: 'Red over black horizontal halves with a yellow half-cogwheel, machete and star in the centre.', t: 'A gear and a machete on red-and-black: "Angola\'s Gear".', s: 'Red for the blood of the liberation struggle, black for Africa; cogwheel = industrial workers, machete = peasants, star = progress and solidarity.' },
  ALB: { f: 'Red field with a black double-headed eagle in the centre.', t: 'Black two-headed eagle on plain red: Albanians call their land Shqipëria, popularly "land of the eagles".', s: 'The eagle derives from the seal of the 15th-century national hero Skanderbeg.' },
  AND: { f: 'Vertical blue, yellow and red bands (yellow slightly wider) with a coat of arms in the yellow band showing a mitre, red-yellow stripes and two cows.', t: 'Looks like Romania or Chad — but with a crest. Find the two cows: "And-cows" = Andorra.', s: 'The arms combine the symbols of the co-princes: the Bishop of Urgell (mitre and crozier) and the Counts of Foix (now the French president), plus Catalonia and Béarn (the cows).' },
  ARE: { f: 'Red vertical band at the hoist with horizontal green, white and black stripes to its right.', t: 'A red "handle" holding three stripes: the Emirates\' flag looks like a flag on a pole.', s: 'Uses the Pan-Arab colours.' },
  ARG: { f: 'Light-blue, white, light-blue horizontal stripes with a golden sun with a face in the centre.', t: 'Sky-blue and white with a smiling sun: "Argentina = Sunny Skies".', s: 'The Sun of May commemorates the May Revolution of 1810; the colours come from Manuel Belgrano\'s cockade.' },
  ARM: { f: 'Horizontal red, blue and orange stripes.', t: 'Red–Blue–Orange: Armenia is famous for apricots, so the apricot-orange is at the bottom.', s: 'Red: the Armenian Highlands and the struggle for survival; blue: the will to live under peaceful skies; orange: creative talent and hard work.' },
  ATG: { f: 'Red field with a large inverted triangle containing black, blue and white bands and a rising golden sun.', t: 'A sunrise over the sea inside a big "V": V for victory, A for Antigua.', s: 'The sun represents the dawn of a new era, black the African heritage, blue hope, red the energy of the people; the V stands for victory.' },
  AUS: { f: 'Dark-blue ensign with the Union Jack, a large white seven-pointed star below it, and five white stars (the Southern Cross) on the fly.', t: 'White stars and a big star under the Union Jack. "Australia has the Big star; New Zealand has red stars."', s: 'The large Commonwealth Star represents the federation of states and territories; the Southern Cross is a constellation seen from the southern hemisphere.' },
  AUT: { f: 'Three equal horizontal stripes: red, white, red.', t: 'Red–white–red "sandwich" with equal slices. Latvia\'s is darker maroon with a thin white stripe.', s: 'Traditionally linked to the legend of Duke Leopold V, whose white tunic was soaked in blood except under his belt.' },
  AZE: { f: 'Horizontal blue, red and green stripes with a white crescent and eight-pointed star in the red stripe.', t: 'Blue–red–green "traffic light" with a moon in the middle.', s: 'Blue: Turkic heritage; red: progress and modernisation; green: Islam. The eight-pointed star is commonly said to represent the eight branches of Turkic peoples.' },
  BDI: { f: 'A white diagonal cross divides red (top and bottom) and green (sides) triangles; a white central disc holds three red six-pointed stars outlined in green.', t: 'A white "X" with a disc of three stars: three stars for the motto Unity, Work, Progress.', s: 'The three stars represent the national motto "Unity, Work, Progress" (and are also associated with the three main ethnic groups).' },
  BEL: { f: 'Vertical black, yellow and red bands; nearly square proportions (13:15).', t: 'Germany\'s colours standing up: Belgium is the vertical one, with yellow in the middle.', s: 'The colours come from the arms of the Duchy of Brabant (a gold lion with red claws on black).' },
  BEN: { f: 'Green vertical band at the hoist; yellow over red horizontal bands to the right.', t: 'A green "spine" on the left holding yellow over red.', s: 'Green: hope; yellow: wealth; red: courage.' },
  BFA: { f: 'Red over green horizontal halves with a yellow five-pointed star in the centre.', t: 'Red over green with a gold star: "Burkina burns red above green fields".', s: 'Red: the revolution; green: agricultural and natural wealth; the yellow star: the guiding light of the revolution.' },
  BGD: { f: 'Dark-green field with a red disc placed slightly toward the hoist.', t: 'A red sun on green — and it sits slightly left so it looks centred when the flag flies.', s: 'The red disc represents the sun rising over Bengal and the blood of those who died for independence; green represents the land.' },
  BGR: { f: 'Horizontal white, green and red stripes.', t: 'White–Green–Red from the top: Bulgaria starts with snow-white peaks.', s: 'White: peace; green: the fertile land; red: the courage of the people.' },
  BHR: { f: 'Bright red field with a white band at the hoist ending in five white triangular points.', t: 'Five points, like the Five Pillars of Islam. Bahrain = bright red & 5 points; Qatar = maroon & 9 points.', s: 'The five white points represent the Five Pillars of Islam.' },
  BHS: { f: 'Aquamarine, gold, aquamarine horizontal stripes with a black triangle at the hoist.', t: 'A beach: sea, sand, sea — with a black triangle pointing in.', s: 'Aquamarine: the surrounding seas; gold: the sun and sands; black: the strength and unity of the people.' },
  BIH: { f: 'Blue field with a large yellow right-angled triangle and a diagonal row of white stars along its long side (stars cut off at both ends).', t: 'A yellow triangle with a line of stars — like the EU flag sliced on a diagonal.', s: 'The triangle evokes the country\'s shape and its three constituent peoples; the stars and blue refer to Europe.' },
  BLR: { f: 'Red over green (2:1) with a vertical red-on-white traditional ornament at the hoist.', t: 'Red over green with a strip of embroidery lace on the left.', s: 'The ornament is a traditional woven pattern (rushnik) symbolising the country\'s cultural heritage.' },
  BLZ: { f: 'Royal-blue field with thin red stripes at top and bottom and a white disc holding a coat of arms with two woodcutters and a mahogany tree.', t: 'The flag with people on it: two woodcutters in a white circle.', s: 'The coat of arms recalls the mahogany logging industry; the motto "Sub Umbra Floreo" means "Under the shade I flourish".' },
  BOL: { f: 'Horizontal red, yellow and green stripes; the state flag adds a coat of arms in the centre.', t: 'Red on top for Bolivia. Ghana has the same order but a black star; Lithuania is yellow–green–red.', s: 'Red: the bravery of the army; yellow: mineral wealth; green: the fertility of the land.' },
  BRA: { f: 'Green field with a large yellow diamond and a blue globe with white stars and a white banner reading "ORDEM E PROGRESSO".', t: 'Green, yellow diamond, starry globe: the football-shirt flag.', s: 'The stars show the sky over Rio de Janeiro on 15 November 1889; each star represents a state or the Federal District.' },
  BRB: { f: 'Vertical ultramarine, gold, ultramarine bands with a black trident head in the centre.', t: 'A trident with the shaft broken off: Barbados "broke" with colonial rule.', s: 'The broken trident symbolises the break from colonial status; blue = sea and sky, gold = sand.' },
  BRN: { f: 'Yellow field crossed by diagonal white and black bands with a red crest in the centre.', t: 'Yellow with a black-and-white diagonal sash and a red crest.', s: 'Yellow is the colour of the Sultan; the white and black bands represent the chief ministers.' },
  BTN: { f: 'Divided diagonally into yellow (upper hoist) and orange (lower fly) with a white dragon across the middle.', t: 'The dragon flag: "Land of the Thunder Dragon".', s: 'Yellow: the secular authority of the king; orange: Buddhist spiritual tradition; the Druk (thunder dragon) holds jewels for wealth.' },
  BWA: { f: 'Light-blue field with a black horizontal stripe bordered in white across the middle.', t: 'Sky-blue with a zebra stripe (black between white).', s: 'Blue represents water and rain ("Pula"); the black and white stripes represent racial harmony and the zebra, the national animal.' },
  CAF: { f: 'Four horizontal stripes — blue, white, green, yellow — crossed by a vertical red band in the centre; a yellow star in the top-left.', t: 'Everything is crossed by a red band in the "centre": Central African Republic.', s: 'Combines the French tricolour colours with Pan-African colours; the red band represents the blood shared by all peoples.' },
  CAN: { f: 'Red-white-red vertical bands (the white centre is a square) with a red eleven-pointed maple leaf.', t: 'The maple leaf.', s: 'The maple leaf has been a symbol of the country since the 18th century.' },
  CHE: { f: 'Square red flag with a bold white cross with equal arms in the centre.', t: 'Square! Only two national flags are square: this one and the Vatican.', s: 'Derived from the banner of the canton of Schwyz.' },
  CHL: { f: 'White over red horizontal bands with a blue square in the top-left containing a white five-pointed star.', t: 'One lone star in a blue box: "Chile has a single chilly star".', s: 'Blue: the sky and Pacific; white: the snow of the Andes; red: blood spilt for independence; the star: a guide to progress and honour.' },
  CHN: { f: 'Red field with one large yellow star and four smaller yellow stars arcing beside it in the top-left.', t: 'A big star with four little stars bowing toward it.', s: 'The large star represents the Communist Party; the four smaller stars are commonly said to represent the social classes of the people.' },
  CIV: { f: 'Vertical orange, white and green bands with orange at the hoist; 2:3 proportions.', t: 'O–W–G: "Orange first". Ireland is the mirror image (Green first) and is longer (1:2).', s: 'Orange: the savannah land; white: peace; green: hope and the forests.' },
  CMR: { f: 'Vertical green, red and yellow bands with a yellow star in the red centre.', t: 'Green–red–yellow with a star in the red middle. Senegal has a green star in a yellow middle.', s: 'Green: southern forests; yellow: the northern savannah and sun; red: unity; the star: unity of the nation.' },
  COD: { f: 'Sky-blue field with a red diagonal band edged in yellow from lower hoist to upper fly and a yellow star in the top-left.', t: 'Blue sky, red diagonal, yellow star in the corner.', s: 'Blue: peace; red: the blood of the country\'s martyrs; yellow: wealth; the star: a radiant future.' },
  COG: { f: 'Divided diagonally by a yellow band from lower hoist to upper fly: green triangle at the hoist, red triangle at the fly; no star.', t: 'Green–yellow–red diagonal, no star and no blue.', s: 'Pan-African colours: green for forests and agriculture, yellow for natural wealth, red for the struggle for independence.' },
  COL: { f: 'Horizontal yellow, blue and red bands where the yellow takes the top half; no emblem.', t: 'A big yellow half with no emblem. Ecuador adds a condor crest; Venezuela has equal bands and stars.', s: 'Yellow: the land\'s wealth; blue: the two oceans; red: the blood shed for independence.' },
  COM: { f: 'Four horizontal stripes — yellow, white, red, blue — with a green triangle at the hoist holding a white crescent and four white stars.', t: 'Four stripes, four stars: four islands.', s: 'The four stripes and four stars represent the islands of the archipelago (Mohéli, Mayotte, Anjouan and Grande Comore).' },
  CPV: { f: 'Blue field with a white-red-white horizontal stripe set below the centre and a circle of ten yellow stars.', t: 'Like the EU flag with a red stripe: ten stars = ten islands.', s: 'The ten stars represent the ten main islands; blue: sea and sky; the stripes: the road to nation-building.' },
  CRI: { f: 'Five horizontal stripes: blue, white, a double-width red, white, blue (state flag adds arms on the red).', t: 'Red in the middle for Costa Rica; Thailand puts blue in the middle.', s: 'Blue: the sky and opportunity; white: peace and wisdom; red: the blood of martyrs and warmth of the people.' },
  CUB: { f: 'Five horizontal blue and white stripes (three blue) with a red triangle at the hoist containing a white star.', t: 'Blue stripes + red triangle. (Puerto Rico swaps them: red stripes + blue triangle.)', s: 'The three blue stripes represent the old military departments; the red triangle the blood shed for independence; the star — La Estrella Solitaria — freedom.' },
  CYP: { f: 'White field with a copper-orange silhouette of an island above two crossed green olive branches.', t: 'A map of the island on the flag, in copper colour.', s: 'The copper colour refers to the island\'s historic copper deposits; the olive branches symbolise peace between the Greek and Turkish communities.' },
  CZE: { f: 'White over red horizontal halves with a blue triangle at the hoist reaching the centre.', t: 'Poland\'s white-over-red with a blue wedge pushed in from the left.', s: 'White and red come from the arms of Bohemia; blue from the arms of Moravia.' },
  DEU: { f: 'Horizontal black, red and gold stripes.', t: 'Black–Red–Gold lying down. Belgium has the same colours standing up.', s: 'The colours date from the uniforms of the Lützow Free Corps in the Napoleonic wars and the 1848 democratic movement.' },
  DJI: { f: 'Light blue over green with a white triangle at the hoist containing a red five-pointed star.', t: 'Sky over grass with a red star in a white wedge.', s: 'Blue: the Issa people and the sea; green: the Afar people and the earth; white: peace; red star: unity.' },
  DMA: { f: 'Green field with a cross of yellow, black and white stripes and a red disc holding a purple parrot surrounded by ten green stars.', t: 'The parrot flag — the only national flag with purple (the Sisserou parrot).', s: 'The ten stars represent the ten parishes; the Sisserou parrot is the national bird.' },
  DNK: { f: 'Red field with a white Scandinavian cross offset toward the hoist.', t: 'Red + white Nordic cross: the original Nordic cross, said to be the oldest national flag in continuous use.', s: 'According to legend the Dannebrog fell from the sky during the Battle of Lyndanisse in 1219.' },
  DOM: { f: 'A centred white cross divides blue and red quarters (blue at top-hoist) with a small coat of arms in the centre.', t: 'White cross + blue/red squares + small shield. Panama uses stars instead of a cross.', s: 'Blue: liberty; red: the blood of heroes; the white cross: sacrifice and faith.' },
  DZA: { f: 'Vertical green and white halves with a red crescent and star in the centre.', t: 'Half green, half white with a red crescent and star.', s: 'Green: Islam; white: purity and peace; the red crescent and star: Islam and the blood of martyrs.' },
  ECU: { f: 'Horizontal yellow (top half), blue and red bands with a coat of arms topped by a condor in the centre.', t: 'Colombia + a condor crest = Ecuador.', s: 'The coat of arms shows Mount Chimborazo, the Guayas river and a condor; colours shared with Colombia and Venezuela from Gran Colombia.' },
  EGY: { f: 'Horizontal red, white and black stripes with a golden eagle in the white stripe.', t: 'The golden eagle. Yemen is plain; Iraq has green writing.', s: 'Red: the revolution; white: the peaceful 1952 revolution; black: the end of oppression. The eagle is the Eagle of Saladin.' },
  ERI: { f: 'A red triangle stretching from hoist to fly divides a green upper and blue lower triangle; a golden olive wreath and branch sit in the red near the hoist.', t: 'A big red arrow pointing right with an olive wreath.', s: 'Green: agriculture; blue: the sea; red: the blood shed for independence; the olive branch: peace.' },
  ESP: { f: 'Red, yellow (double width), red horizontal stripes with the coat of arms toward the hoist.', t: 'Red–yellow–red with a fat yellow middle and a crest shifted left.', s: 'The coat of arms combines the historic kingdoms and the Pillars of Hercules with the motto "Plus Ultra".' },
  EST: { f: 'Horizontal blue, black and white stripes.', t: 'Blue sky, black earth, white snow.', s: 'Commonly interpreted as the sky, the native soil and the hope for happiness (or the snow).' },
  ETH: { f: 'Horizontal green, yellow and red stripes with a blue disc containing a yellow star with rays in the centre.', t: 'Green–yellow–red with a blue star disc. Its colours inspired many Pan-African flags.', s: 'Green: the land; yellow: hope and peace; red: sacrifice. The emblem represents the equality and unity of the nations and peoples.' },
  FIN: { f: 'White field with a blue Scandinavian cross.', t: 'Blue lakes on white snow.', s: 'Blue for the lakes and sky, white for the snow of winter.' },
  FJI: { f: 'Light-blue ensign with the Union Jack in the top-left and a shield showing a lion, sugar cane, a coconut palm, a dove and bananas.', t: 'A sky-blue British ensign with a fruit-and-palm shield.', s: 'The light blue represents the Pacific; the shield depicts the main agricultural products and a dove of peace.' },
  FRA: { f: 'Vertical blue, white and red bands with blue at the hoist.', t: 'Blue–White–Red standing up. The Netherlands has the same colours lying down.', s: 'Blue and red are the colours of Paris; white was the colour of the monarchy — united in the Revolution.' },
  FSM: { f: 'Light-blue field with four white five-pointed stars arranged in a diamond.', t: 'Four white stars on sky blue: four states.', s: 'The four stars represent the four states: Chuuk, Kosrae, Pohnpei and Yap.' },
  GAB: { f: 'Horizontal green, yellow and blue stripes; 3:4 proportions.', t: 'Forest, equator, sea: green–yellow–blue.', s: 'Green: the forests; yellow: the equator and sun; blue: the sea.' },
  GBR: { f: 'Blue field with a red cross edged in white over red and white diagonal crosses (the Union Jack).', t: 'The Union Jack itself.', s: 'Combines the crosses of St George (England), St Andrew (Scotland) and St Patrick (Ireland).' },
  GEO: { f: 'White field with a large red cross and a smaller red cross in each of the four quarters.', t: 'Five crosses on white.', s: 'The St George\'s cross with four bolnur-katskhuri crosses; a medieval Georgian banner revived in 2004.' },
  GHA: { f: 'Horizontal red, yellow and green stripes with a black five-pointed star in the yellow centre.', t: 'The black star — the national football team is the "Black Stars".', s: 'Red: the blood of the independence struggle; gold: mineral wealth; green: forests; the black star: African freedom.' },
  GIN: { f: 'Vertical red, yellow and green bands with red at the hoist.', t: 'Red–Yellow–Green from the left. Mali is the reverse (Green first).', s: 'Red: sacrifice; yellow: the sun and wealth; green: vegetation — matching the motto Work, Justice, Solidarity.' },
  GMB: { f: 'Horizontal red, blue and green stripes with thin white stripes edging the blue.', t: 'A blue river running through red and green: the Gambia River.', s: 'Red: the sun and savannah; blue: the Gambia River; green: the forests; white: unity and peace.' },
  GNB: { f: 'Vertical red band at the hoist with a black star; yellow over green horizontal bands to the right.', t: 'A red bar with a black star, then yellow over green.', s: 'The black star represents African unity; Pan-African colours shared with its neighbours.' },
  GNQ: { f: 'Horizontal green, white and red stripes with a blue triangle at the hoist and a coat of arms with a silk-cotton tree in the centre.', t: 'A blue triangle and a tree in the middle.', s: 'Green: natural resources; white: peace; red: the independence struggle; blue: the sea linking the mainland and islands. The six stars on the arms represent the mainland and five islands.' },
  GRC: { f: 'Nine horizontal blue and white stripes with a blue canton containing a white cross.', t: 'Blue and white stripes with a cross — the Aegean on a flag.', s: 'The nine stripes are popularly said to match the nine syllables of "Eleftheria i Thanatos" ("Freedom or Death").' },
  GRD: { f: 'Red border holding six yellow stars; inside, diagonal yellow and green triangles, a red disc with a star in the centre and a nutmeg at the hoist.', t: 'The nutmeg flag — find the little nutmeg on the left.', s: 'The seven stars represent the seven parishes; the nutmeg refers to the island\'s famous spice.' },
  GTM: { f: 'Vertical sky-blue, white, sky-blue bands with a coat of arms featuring a quetzal bird in the centre.', t: 'Sky-blue standing stripes with the quetzal bird.', s: 'The blue bands represent the Pacific and Caribbean; the quetzal symbolises liberty.' },
  GUY: { f: 'Green field with a yellow arrowhead edged in white and a red triangle edged in black pointing toward the fly.', t: '"The Golden Arrowhead" — its official nickname.', s: 'Green: agriculture and forests; yellow: mineral wealth; red: zeal; black: endurance.' },
  HND: { f: 'Blue, white, blue horizontal stripes with five blue stars in an X pattern in the centre.', t: 'Five stars in the middle like the five dots on a die.', s: 'The five stars represent the five former members of the Federal Republic of Central America.' },
  HRV: { f: 'Horizontal red, white and blue stripes with a red-and-white checkerboard shield topped by a crown of five small shields.', t: 'The checkerboard.', s: 'The checkerboard (šahovnica) is the historic Croatian coat of arms; the crown shows five historic regions.' },
  HTI: { f: 'Blue over red horizontal halves with a white panel in the centre showing a palm tree, cannons and flags.', t: 'Blue over red with a white panel holding a palm tree.', s: 'Created from the French tricolour with the white removed; the arms show a royal palm with a Phrygian cap of liberty.' },
  HUN: { f: 'Horizontal red, white and green stripes.', t: 'Italy\'s colours lying down.', s: 'Red: strength; white: faithfulness; green: hope.' },
  IDN: { f: 'Red over white horizontal halves; 2:3 proportions.', t: 'Red over white and long. Monaco is identical in colour but almost square (4:5); Poland is the other way up.', s: 'Red: courage; white: purity. Known as Sang Saka Merah-Putih.' },
  IND: { f: 'Horizontal saffron, white and green stripes with a navy-blue 24-spoke wheel in the centre.', t: 'The wheel (Ashoka Chakra). Niger has an orange disc instead.', s: 'Saffron: courage and sacrifice; white: truth and peace; green: faith and fertility; the wheel: the law of dharma.' },
  IRL: { f: 'Vertical green, white and orange bands with green at the hoist; long 1:2 proportions.', t: 'G–W–O: "Green Goes first", like a shamrock. Côte d\'Ivoire is the mirror image and shorter.', s: 'Green: the Gaelic tradition; orange: followers of William of Orange; white: lasting peace between them.' },
  IRN: { f: 'Horizontal green, white and red stripes with a red emblem in the centre and stylised Arabic script repeated along the edges of the white stripe.', t: 'Green–white–red with a red tulip-like emblem and a "fringe" of script.', s: 'The phrase "Allahu Akbar" is repeated 22 times, referring to the date of the 1979 revolution (22 Bahman).' },
  IRQ: { f: 'Horizontal red, white and black stripes with green Arabic script in the white stripe.', t: 'Green writing on the white: Iraq.', s: 'The green script reads "Allahu Akbar" (God is Great); Pan-Arab colours.' },
  ISL: { f: 'Blue field with a red Scandinavian cross outlined in white.', t: 'Ice and fire: blue with a red cross. Norway is the reverse (red with blue cross).', s: 'Blue: the mountains and sea; white: ice and snow; red: volcanic fire.' },
  ISR: { f: 'White field with two horizontal blue stripes and a blue six-pointed star in the centre.', t: 'Blue stripes like a prayer shawl with the Star of David.', s: 'The design recalls the tallit (prayer shawl); the Star of David is a symbol of Judaism.' },
  ITA: { f: 'Vertical green, white and red bands with green at the hoist.', t: 'Pizza margherita: basil, mozzarella, tomato. Mexico adds an eagle.', s: 'Commonly said to represent hope (green), faith (white) and charity (red).' },
  JAM: { f: 'A gold diagonal cross with green triangles at top and bottom and black triangles at the hoist and fly.', t: 'The only national flag with no red, white or blue.', s: 'Black: strength and creativity; gold: sunlight and natural wealth; green: the land and hope.' },
  JOR: { f: 'Horizontal black, white and green stripes with a red triangle at the hoist containing a white seven-pointed star.', t: 'Palestine\'s flag plus a white star.', s: 'The star\'s seven points stand for the seven verses of the opening chapter of the Qur\'an; colours of the Arab Revolt.' },
  JPN: { f: 'White field with a red disc in the centre.', t: 'The rising sun — red disc, white field.', s: 'Hinomaru, "circle of the sun".' },
  KAZ: { f: 'Sky-blue field with a golden sun above a soaring eagle and a vertical golden ornament at the hoist.', t: 'Turquoise sky, golden sun and an eagle.', s: 'Blue: the sky and the Turkic peoples; the sun: life and energy; the steppe eagle: freedom.' },
  KEN: { f: 'Horizontal black, red and green stripes separated by thin white stripes, with a red, black and white Maasai shield and two spears.', t: 'The Maasai shield and crossed spears.', s: 'Black: the people; red: the blood shed for independence; green: the land; white: peace; the shield: defence of freedom.' },
  KGZ: { f: 'Red field with a yellow sun with 40 straight rays enclosing a red crossed lattice (a yurt crown).', t: 'A yurt roof seen from inside, framed by a sun.', s: 'The 40 rays refer to the 40 tribes united by the hero Manas; the tunduk is the crown of a yurt.', n: 'Updated in December 2023: the sun\'s rays were made straight instead of wavy.' },
  KHM: { f: 'Blue, double-width red, blue horizontal stripes with a white temple (Angkor Wat) in the centre.', t: 'A building on a flag: the temple of Angkor Wat.', s: 'Angkor Wat represents the nation\'s heritage; blue: the monarchy; red: the nation; white: religion.' },
  KIR: { f: 'Upper half red with a golden frigatebird over a rising sun; lower half blue and white wavy lines.', t: 'A bird flying over a sunrise over the ocean.', s: 'The frigatebird represents power and freedom; the waves represent the Pacific; the sun the equator.' },
  KNA: { f: 'A wide black diagonal band edged in yellow with two white stars, dividing a green triangle (upper hoist) from a red triangle (lower fly).', t: 'Two stars on the diagonal: two islands.', s: 'The two stars represent hope and liberty (often associated with the two islands); green: fertility; red: the struggle; black: African heritage.' },
  KOR: { f: 'White field with a red-and-blue circle (taegeuk) in the centre and four black trigrams in the corners.', t: 'Yin-yang with four Morse-code-like trigrams.', s: 'White: peace and purity; the taegeuk: the balance of the universe; the trigrams: heaven, earth, water and fire.' },
  KWT: { f: 'Horizontal green, white and red stripes with a black trapezoid at the hoist.', t: 'A black trapezoid (not a triangle) at the hoist.', s: 'Pan-Arab colours representing deeds, battles, land and the future.' },
  LAO: { f: 'Red, double-width blue, red horizontal stripes with a white disc in the centre.', t: 'A full moon over the Mekong river.', s: 'Red: blood shed for freedom; blue: prosperity; the white disc: the moon over the Mekong and national unity.' },
  LBN: { f: 'Red, double-width white, red horizontal stripes with a green cedar tree in the centre.', t: 'The cedar tree.', s: 'The cedar of Lebanon symbolises holiness, eternity and peace; red the blood shed for liberation.' },
  LBR: { f: 'Eleven red and white horizontal stripes with a blue square canton containing one white star.', t: 'A US flag with one star: "the Lone Star of Africa".', s: 'The eleven stripes represent the signatories of the Declaration of Independence; the star a beacon of freedom in Africa.' },
  LBY: { f: 'Horizontal red, double-width black and green stripes with a white crescent and star in the black.', t: 'Black in the middle with a white crescent and star.', s: 'The flag of the 1951 kingdom, restored in 2011; red, black and green for the three historic regions.' },
  LCA: { f: 'Cerulean field with a black triangle edged in white over a yellow triangle, forming twin peaks.', t: 'Two mountain peaks: the Pitons.', s: 'The triangles evoke the twin Pitons volcanic peaks; blue: the sea and sky; yellow: sunshine.' },
  LIE: { f: 'Blue over red horizontal halves with a golden crown in the top-left.', t: 'Blue over red with a crown in the corner. Haiti has a white panel in the centre.', s: 'The crown was added in 1937 after the flag was found identical to Haiti\'s at the 1936 Olympics.' },
  LKA: { f: 'A gold border around a maroon panel with a golden lion holding a sword, bo leaves in the corners, and green and orange vertical bands at the hoist.', t: 'The lion with a sword.', s: 'The lion represents the Sinhalese people; the green and orange bands the Muslim and Tamil communities; the bo leaves Buddhist virtues.' },
  LSO: { f: 'Horizontal blue, white and green stripes with a black Basotho hat in the centre.', t: 'The hat (mokorotlo).', s: 'Blue: sky and rain; white: peace; green: prosperity; the hat is a symbol of the Basotho people.' },
  LTU: { f: 'Horizontal yellow, green and red stripes.', t: 'Sun, forest, blood: yellow–green–red.', s: 'Yellow: the sun and prosperity; green: forests and hope; red: courage and blood shed for the country.' },
  LUX: { f: 'Horizontal red, white and light-blue stripes.', t: 'L for Light blue. The Netherlands uses a darker blue and a shorter flag.', s: 'Colours from the coat of arms of the House of Luxembourg (a red lion on white and blue stripes).' },
  LVA: { f: 'Dark carmine-red field with a narrow white horizontal stripe (2:1:2).', t: 'Dark wine-red with a thin white stripe. Austria\'s stripes are equal and brighter.', s: 'Legend tells of a wounded chieftain wrapped in a white sheet that was stained red except where he lay.' },
  MAR: { f: 'Red field with a green interlaced five-pointed star outline in the centre.', t: 'A green star outline on red.', s: 'The green pentagram (Seal of Solomon) represents the five pillars of Islam; red recalls the ruling Alaouite dynasty.' },
  MCO: { f: 'Red over white horizontal halves; nearly square (4:5).', t: 'Monaco is the "chunky" one: almost square. Indonesia is longer.', s: 'Red and white are the heraldic colours of the House of Grimaldi.' },
  MDA: { f: 'Vertical blue, yellow and red bands with a coat of arms of an eagle holding a cross, with an aurochs head on its shield.', t: 'Romania + an eagle crest = Moldova.', s: 'The colours are shared with Romania; the eagle and aurochs head are historic symbols of Moldavia.' },
  MDG: { f: 'White vertical band at the hoist; red over green horizontal bands to the right.', t: 'A white bar on the left, red over green.', s: 'White: purity; red: sovereignty; green: hope and the coastal population.' },
  MDV: { f: 'Red field with a large green rectangle containing a white crescent.', t: 'A green box with a crescent inside a red frame.', s: 'Red: the blood of national heroes; green: peace and prosperity; the crescent: Islam.' },
  MEX: { f: 'Vertical green, white and red bands with an eagle on a cactus eating a snake in the centre; 4:7 proportions.', t: 'Italy + an eagle eating a snake.', s: 'The emblem recalls the Aztec legend of the founding of Tenochtitlan.' },
  MHL: { f: 'Blue field with orange and white diagonal bands widening toward the fly and a white star with 24 points.', t: 'Diagonal rays and a 24-point star.', s: 'The 24 points represent the municipal districts; orange and white represent the two island chains.' },
  MKD: { f: 'Red field with a yellow sun whose eight rays widen out to the edges.', t: 'A sun bursting its rays to every edge.', s: 'The "new sun of liberty" from the national anthem.' },
  MLI: { f: 'Vertical green, yellow and red bands with green at the hoist.', t: 'Green–Yellow–Red from the left: "Mali = Mint first". Guinea is the reverse.', s: 'Green: fertility; gold: purity and mineral wealth; red: blood shed for independence.' },
  MLT: { f: 'Vertical white and red halves with a George Cross edged in red in the top-left.', t: 'Half white, half red, with a small cross medal.', s: 'The George Cross was awarded to the island by King George VI in 1942 for bravery during the Second World War.' },
  MMR: { f: 'Horizontal yellow, green and red stripes with a large white five-pointed star in the centre.', t: 'A big white star over yellow–green–red.', s: 'Yellow: solidarity; green: peace and tranquillity; red: courage; the star: the union.' },
  MNE: { f: 'Red field with a gold border and a golden double-headed eagle holding a sceptre and orb, with a lion on its chest.', t: 'Gold border + golden eagle. Albania has a black eagle and no border.', s: 'The eagle and lion come from the historic arms of the Petrović-Njegoš dynasty.' },
  MNG: { f: 'Vertical red, blue and red bands with a yellow Soyombo symbol on the hoist band.', t: 'Red–blue–red with a stacked yellow symbol (Soyombo) on the left.', s: 'Blue: the eternal blue sky; red: progress and prosperity; the Soyombo: the national symbol.' },
  MOZ: { f: 'Horizontal green, black and yellow stripes edged in white, with a red triangle at the hoist containing a star, a book, a rifle and a hoe.', t: 'The only national flag with a modern rifle (an AK-47).', s: 'The book: education; the hoe: agriculture; the rifle: defence and vigilance; the star: internationalism.' },
  MRT: { f: 'Green field with a gold crescent and star, with red stripes along the top and bottom edges.', t: 'Green with a gold crescent, framed by red stripes.', s: 'Green and gold: Islam and the Sahara; the red stripes (added in 2017) honour those who fought for independence.' },
  MUS: { f: 'Four equal horizontal stripes: red, blue, yellow and green.', t: 'A four-colour rainbow.', s: 'Red: the struggle for independence; blue: the Indian Ocean; yellow: the light of independence; green: agriculture.' },
  MWI: { f: 'Horizontal black, red and green stripes with a red rising sun in the black stripe.', t: 'A red sun rising at the top.', s: 'Black: the people; red: the blood of martyrs; green: nature; the rising sun: the dawn of freedom and hope.' },
  MYS: { f: 'Fourteen red and white stripes with a blue canton containing a yellow crescent and fourteen-pointed star.', t: 'Stars-and-stripes look with a crescent and big yellow star.', s: 'The 14 stripes and 14 points represent the 13 states and the federal government.' },
  NAM: { f: 'A red diagonal band edged in white divides a blue upper hoist (with a golden sun) from a green lower fly.', t: 'Blue–red–green diagonal with a golden sun in the corner.', s: 'Blue: sky and ocean; red: the people; green: vegetation; white: peace; the sun: life and energy.' },
  NER: { f: 'Horizontal orange, white and green stripes with an orange disc in the centre; nearly square (6:7).', t: 'India-like but with an orange sun instead of a wheel, and almost square.', s: 'Orange: the Sahara; white: purity; green: the fertile south; the disc: the sun.' },
  NGA: { f: 'Vertical green, white and green bands.', t: 'Green–white–green standing up.', s: 'Green: agriculture and forests; white: peace and unity.' },
  NIC: { f: 'Blue, white, blue horizontal stripes with a circular emblem in the centre showing a triangle with volcanoes and a rainbow.', t: 'The rainbow inside the triangle. El Salvador\'s emblem has a laurel wreath instead.', s: 'The triangle represents equality; the five volcanoes the five Central American nations; the rainbow peace.' },
  NLD: { f: 'Horizontal red, white and blue stripes.', t: 'Red–white–blue lying down with a dark blue. Luxembourg has light blue.', s: 'Derived from the orange-white-blue flag of William of Orange; the orange became red in the 17th century.' },
  NOR: { f: 'Red field with a blue Scandinavian cross outlined in white.', t: '"Mother of flags": contains the colours of all its neighbours — red, white and blue.', s: 'Red, white and blue express the ideals of liberty; the cross reflects the Nordic and Christian heritage.' },
  NPL: { f: 'Two stacked crimson pennants with a blue border; a white moon in the upper and a white sun in the lower pennant.', t: 'The only non-rectangular national flag.', s: 'The two pennants are often associated with the Himalayas and the two religions; the moon and sun express the hope that the nation will last as long as they do.' },
  NRU: { f: 'Blue field with a thin yellow horizontal stripe and a white twelve-pointed star below it.', t: 'A star just below the "equator" line.', s: 'The stripe is the equator and the star the island\'s position just south of it; the 12 points represent the 12 original tribes.' },
  NZL: { f: 'Dark-blue ensign with the Union Jack and four red stars outlined in white.', t: 'Four red stars. Australia has white stars plus a big star under the Union Jack.', s: 'The four stars represent the Southern Cross.' },
  OMN: { f: 'White, red and green horizontal stripes with a vertical red band at the hoist and the national emblem (a dagger and crossed swords) in the top-left.', t: 'A red "L" with a dagger and swords in the corner.', s: 'White: peace; red: battles against invaders; green: fertility. The emblem is a khanjar with crossed swords.' },
  PAK: { f: 'Dark-green field with a white vertical band at the hoist and a white crescent and star.', t: 'Green with a white strip on the left and a crescent and star.', s: 'Green: the Muslim majority; white: religious minorities; the crescent: progress; the star: light and knowledge.' },
  PAN: { f: 'Quartered: white with a blue star (top hoist), red (top fly), blue (bottom hoist), white with a red star (bottom fly).', t: 'Four squares with two stars. The Dominican Republic has a white cross instead.', s: 'Blue and red: the two historic political parties; white: peace between them.' },
  PER: { f: 'Vertical red, white and red bands (the state flag adds a coat of arms in the centre).', t: 'Red–white–red standing up. Canada has a maple leaf; Austria is horizontal.', s: 'Red and white are said to have been inspired by flamingos seen by San Martín.' },
  PHL: { f: 'Blue over red horizontal halves with a white triangle at the hoist containing a golden eight-rayed sun and three golden stars.', t: 'The sun with eight rays and three stars in a white triangle.', s: 'The eight rays represent the first eight provinces to revolt against Spain; the three stars Luzon, Visayas and Mindanao.', n: 'In wartime the flag is flown with the red stripe on top.' },
  PLW: { f: 'Light-blue field with a yellow disc placed slightly toward the hoist.', t: 'A full moon over the Pacific. Bangladesh has a red sun on green.', s: 'The disc is the full moon, a symbol of peace and the right time for harvest; blue: the ocean.' },
  PNG: { f: 'Divided diagonally: red upper fly with a yellow bird of paradise; black lower hoist with five white stars.', t: 'A bird of paradise above the Southern Cross.', s: 'Red and black are traditional colours; the bird of paradise is a national symbol; the stars form the Southern Cross.' },
  POL: { f: 'White over red horizontal halves.', t: 'White on top. Indonesia and Monaco are red on top.', s: 'The colours come from the coat of arms: a white eagle on a red field.' },
  PRK: { f: 'Blue, thin white, wide red, thin white, blue horizontal stripes with a red star in a white disc toward the hoist.', t: 'A red star in a white circle on a wide red band.', s: 'Red: revolutionary traditions; white: purity; blue: sovereignty; the star: socialism.' },
  PRT: { f: 'Vertical green (2/5) and red (3/5) fields with an armillary sphere and shield on the dividing line.', t: 'Green and red with an armillary sphere: the navigator\'s flag.', s: 'The armillary sphere recalls the Age of Discovery; the shield holds castles and five small shields (quinas).' },
  PRY: { f: 'Horizontal red, white and blue stripes with a circular emblem in the centre; the front and back show different emblems.', t: 'Red–white–blue with a small seal — and two different sides.', s: 'One of the very few national flags with different designs on each side (national arms and treasury seal).' },
  PSE: { f: 'Horizontal black, white and green stripes with a red triangle at the hoist.', t: 'Jordan without the star.', s: 'The colours of the 1916 Arab Revolt flag.' },
  QAT: { f: 'Maroon field with a broad white band at the hoist separated by nine serrated points; very long (11:28).', t: 'Maroon, 9 points and very long. Bahrain is brighter red with 5 points.', s: 'The nine points are commonly said to mark Qatar as the ninth member of the "reconciled emirates" of the Persian Gulf (1916); maroon developed from red dried in the sun.' },
  ROU: { f: 'Vertical blue, yellow and red bands of equal width.', t: 'Romania = "Royal blue", lighter than Chad\'s dark indigo blue.', s: 'The colours of the historic principalities of Wallachia and Moldavia.', n: 'Almost identical to Chad\'s flag; Romania\'s blue is lighter.' },
  RUS: { f: 'Horizontal white, blue and red stripes.', t: 'White–Blue–Red, no emblem. Slovakia and Slovenia add a shield.', s: 'Introduced by Peter the Great, inspired by the Dutch flag.' },
  RWA: { f: 'Horizontal sky-blue (half), yellow and green stripes with a golden sun in the top-right.', t: 'Sky, sun and land, with the sun in the upper fly.', s: 'Blue: happiness and peace; yellow: economic development; green: prosperity; the sun: enlightenment.' },
  SAU: { f: 'Green field with white Arabic script (the Shahada) above a horizontal sword.', t: 'Script and a sword on green.', s: 'The script is the Islamic declaration of faith; the sword symbolises justice.', n: 'Because it carries the Shahada, the flag is traditionally never flown at half-mast.' },
  SDN: { f: 'Horizontal red, white and black stripes with a green triangle at the hoist.', t: 'Red on top + green triangle. Palestine and Jordan have black on top and a red triangle.', s: 'Red: the struggle; white: peace; black: the country\'s name ("land of the blacks"); green: Islam and prosperity.' },
  SEN: { f: 'Vertical green, yellow and red bands with a green star in the yellow centre.', t: 'Mali + a green star = Senegal.', s: 'Green: Islam and hope; yellow: wealth; red: the blood of the struggle; the star: unity.' },
  SGP: { f: 'Red over white halves with a white crescent and five white stars in the top-left.', t: 'Red over white with a crescent and five stars.', s: 'Red: brotherhood; white: purity; the crescent: a young nation; the five stars: democracy, peace, progress, justice and equality.' },
  SLB: { f: 'A thin yellow diagonal stripe divides a blue upper hoist (with five white stars) from a green lower fly.', t: 'Blue and green split by a yellow diagonal, with five stars.', s: 'The five stars represent the main island groups; blue: water; green: land; yellow: sunshine.' },
  SLE: { f: 'Horizontal green, white and blue stripes.', t: 'Green–white–blue: hills, justice, the harbour of Freetown.', s: 'Green: agriculture and the mountains; white: unity and justice; blue: the natural harbour of Freetown.' },
  SLV: { f: 'Blue, white, blue horizontal stripes with a coat of arms showing a triangle in a laurel wreath with a text ring (state flag).', t: 'A laurel wreath around a triangle. Nicaragua shows a rainbow and no wreath.', s: 'The blue stripes represent the two oceans; the triangle the three branches of government.' },
  SMR: { f: 'White over light-blue halves with a coat of arms showing three towers on three peaks.', t: 'Three towers on white and light blue.', s: 'The three towers (Guaita, Cesta and Montale) stand on Monte Titano.' },
  SOM: { f: 'Light-blue field with a large white five-pointed star in the centre.', t: 'A single white star on light blue.', s: 'The five points represent the five regions where Somali people live.' },
  SRB: { f: 'Horizontal red, blue and white stripes with a crowned double-headed eagle coat of arms toward the hoist.', t: 'Red–Blue–White with an eagle. Russia\'s order is white–blue–red.', s: 'Pan-Slavic colours; the white double-headed eagle derives from Byzantine heraldry.' },
  SSD: { f: 'Horizontal black, red and green stripes edged in white with a blue triangle at the hoist containing a yellow star.', t: 'A blue triangle with a yellow star over black–red–green.', s: 'Black: the people; red: blood shed for freedom; green: the land; blue: the Nile; the star: unity.' },
  STP: { f: 'Horizontal green, yellow and green stripes with a red triangle at the hoist and two black stars in the yellow.', t: 'Two black stars: two islands.', s: 'The two stars represent the two main islands; green: vegetation; yellow: the sun and cocoa.' },
  SUR: { f: 'Horizontal green, white, wide red, white and green stripes with a yellow star in the centre.', t: 'A yellow star on a wide red band between green stripes.', s: 'Green: fertility; white: justice and freedom; red: progress; the star: unity and a golden future.' },
  SVK: { f: 'Horizontal white, blue and red stripes with a red shield bearing a white double cross on three blue hills toward the hoist.', t: 'Russia + a shield with a double cross on hills.', s: 'The double cross on three hills (Tatra, Fatra, Mátra) is the Slovak coat of arms.' },
  SVN: { f: 'Horizontal white, blue and red stripes with a shield in the upper hoist showing a white mountain, wavy blue lines and three gold stars.', t: 'Russia + a mountain shield (Triglav) in the corner.', s: 'The shield shows Mount Triglav, the rivers and sea, and the stars of the Counts of Celje.' },
  SWE: { f: 'Blue field with a yellow Scandinavian cross.', t: 'Blue and yellow cross.', s: 'The colours derive from the coat of arms of three gold crowns on blue.' },
  SWZ: { f: 'Horizontal blue, yellow, wide crimson, yellow and blue stripes with a black-and-white shield and spears in the centre.', t: 'A black-and-white warrior shield on crimson.', s: 'Red: past battles; blue: peace; yellow: resources; the Nguni shield: protection.' },
  SYC: { f: 'Five oblique bands — blue, yellow, red, white and green — fanning out from the lower hoist.', t: 'A fan of five colours from the bottom-left corner.', s: 'The rays symbolise a dynamic new country moving into the future.' },
  SYR: { f: 'Horizontal green, white and black stripes with three red five-pointed stars in the white stripe.', t: 'Green on top with three red stars.', s: 'The independence flag of 1932–1958, used by the opposition from 2011.', n: 'Adopted again as the national flag in 2025. The previous flag (red–white–black with two green stars) is no longer used.' },
  TCD: { f: 'Vertical dark-blue, yellow and red bands of equal width.', t: 'Chad = "Dark" indigo blue. Romania\'s blue is lighter.', s: 'Blue: the sky and hope; yellow: the sun and desert; red: progress and sacrifice.', n: 'Almost identical to Romania\'s flag; Chad\'s blue is darker.' },
  TGO: { f: 'Five horizontal green and yellow stripes with a red square in the top-left containing a white star.', t: 'Green and yellow stripes with a red box and white star.', s: 'The five stripes represent the five regions; the white star: hope; red: blood shed for independence.' },
  THA: { f: 'Five horizontal stripes: red, white, double-width blue, white, red.', t: 'Blue in the middle (Costa Rica has red in the middle).', s: 'Red: the nation; white: religion; blue: the monarchy.' },
  TJK: { f: 'Horizontal red, wider white and green stripes with a gold crown under an arc of seven stars in the centre.', t: 'Hungary-like with a crown and seven stars.', s: 'Red: unity; white: purity and cotton; green: the valleys; the crown and stars: the people\'s sovereignty.' },
  TKM: { f: 'Green field with a vertical red stripe near the hoist containing five carpet patterns, plus a white crescent and five stars.', t: 'A carpet stripe on green.', s: 'The five carpet guls represent the major tribes; the five stars the provinces.' },
  TLS: { f: 'Red field with a yellow triangle overlapped by a black triangle at the hoist; a white star in the black.', t: 'A black-and-yellow arrow with a white star.', s: 'Yellow: colonialism; black: obscurantism to be overcome; red: the struggle; the white star: peace.' },
  TON: { f: 'Red field with a white canton containing a red cross.', t: 'Red flag with a small red cross in a white corner.', s: 'The cross symbolises Christianity; red the blood of Christ.' },
  TTO: { f: 'Red field with a black diagonal band edged in white from top-left to bottom-right.', t: 'A black diagonal stripe edged white on red.', s: 'Red: vitality; black: dedication; white: the sea.' },
  TUN: { f: 'Red field with a white disc in the centre containing a red crescent and star.', t: 'A white circle with a red crescent. Türkiye has no circle.', s: 'The crescent and star are traditional symbols of Islam; red recalls the Ottoman heritage.' },
  TUR: { f: 'Red field with a white crescent and a white star toward the hoist.', t: 'Crescent and star directly on red, no circle.', s: 'Legend links the design to the reflection of the moon and a star in a pool of blood.' },
  TUV: { f: 'Light-blue ensign with the Union Jack and nine yellow five-pointed stars.', t: 'Sky-blue British ensign with nine yellow stars: nine islands.', s: 'The nine stars represent the nine islands.' },
  TZA: { f: 'A black diagonal band edged in yellow from lower hoist to upper fly divides green (upper hoist) and blue (lower fly).', t: 'Green and blue split by a black-and-yellow diagonal.', s: 'Green: vegetation; blue: lakes and the ocean; black: the people; yellow: mineral wealth.' },
  UGA: { f: 'Six horizontal stripes (black, yellow, red, repeated) with a white disc in the centre showing a grey crowned crane.', t: 'The crowned crane.', s: 'Black: the people; yellow: the sun; red: brotherhood. The grey crowned crane is the national bird.' },
  UKR: { f: 'Blue over yellow horizontal halves.', t: 'Blue sky over golden wheat fields.', s: 'Commonly interpreted as the blue sky over golden wheat fields.' },
  URY: { f: 'Nine white and blue horizontal stripes with a white canton containing a golden sun with a face.', t: 'Stripes plus a sun in the corner. Argentina has the sun in the centre.', s: 'The nine stripes represent the original departments; the Sun of May symbolises independence.' },
  USA: { f: 'Thirteen red and white stripes with a blue canton containing fifty white stars.', t: 'Stars and Stripes — 50 stars.', s: 'The 13 stripes represent the original colonies; the 50 stars the states.' },
  UZB: { f: 'Horizontal blue, white and green stripes separated by thin red lines, with a white crescent and twelve stars in the blue.', t: 'Blue–white–green with a crescent and twelve stars.', s: 'Blue: water and sky; white: peace; green: nature; red lines: life force; twelve stars: the months of the year.' },
  VAT: { f: 'Square flag divided vertically into yellow and white with crossed gold and silver keys under a papal tiara on the white side.', t: 'Square, yellow and white with the keys of St Peter.', s: 'The keys represent the keys of heaven given to St Peter; the tiara the papacy.' },
  VCT: { f: 'Vertical blue, wide gold and green bands with three green diamonds in a V shape in the centre.', t: 'Three diamonds forming a V for St Vincent.', s: 'The diamonds form a V and represent the islands as the "gems of the Antilles".' },
  VEN: { f: 'Equal horizontal yellow, blue and red stripes with an arc of eight white stars in the blue (state flag adds a coat of arms).', t: 'Equal stripes with an arc of stars. Colombia\'s yellow is a half; Ecuador has a condor.', s: 'The eight stars represent the provinces that signed the 1811 Declaration of Independence.' },
  VNM: { f: 'Red field with a large yellow five-pointed star in the centre.', t: 'One gold star on red.', s: 'Red: revolution and blood; the five points: workers, farmers, soldiers, intellectuals and youth.' },
  VUT: { f: 'Red over green with a black triangle at the hoist edged by a yellow "Y", containing a boar\'s tusk and fern leaves.', t: 'A yellow Y on its side with a curled boar\'s tusk.', s: 'The Y shape represents the islands\' layout; the boar\'s tusk prosperity; the namele leaves peace.' },
  WSM: { f: 'Red field with a blue canton containing five white stars (the Southern Cross).', t: 'Red with a blue corner full of stars.', s: 'The stars represent the Southern Cross; red: courage; blue: freedom; white: purity.' },
  YEM: { f: 'Horizontal red, white and black stripes with no emblem.', t: 'Plain red–white–black. Egypt adds an eagle; Iraq adds green writing.', s: 'Red: the blood of martyrs; white: a bright future; black: the dark past.' },
  ZAF: { f: 'A green Y-shape edged in white and gold, with a black triangle at the hoist, red at the top and blue at the bottom.', t: 'The six-colour "Y" — roads coming together.', s: 'The converging Y represents the convergence of diverse elements within society.' },
  ZMB: { f: 'Green field with an orange eagle in the upper fly above vertical red, black and orange stripes in the lower fly.', t: 'An eagle flying above three stripes in the corner.', s: 'Green: natural resources; red: the freedom struggle; black: the people; orange: mineral wealth; the eagle: the ability to rise above problems.' },
  ZWE: { f: 'Seven horizontal stripes of green, yellow, red and black with a white triangle at the hoist containing a red star and a yellow bird.', t: 'The Zimbabwe bird on a white triangle.', s: 'The soapstone Zimbabwe Bird comes from the ruins of Great Zimbabwe; the red star represents peace.' },

  // ---------- bonus entities ----------
  TWN: { f: 'Red field with a blue canton containing a white sun with twelve rays.', t: 'White sun with 12 rays in a blue corner.', s: '"Blue sky, white sun, and a wholly red earth"; the twelve rays represent the twelve months and hours.' },
  UNK: { f: 'Blue field with a golden map of the territory and an arc of six white stars.', t: 'A golden map under six stars.', s: 'The six stars represent the main ethnic groups.' },
  GRL: { f: 'White over red halves with a counter-coloured disc (red top, white bottom) toward the hoist.', t: 'A setting sun over the ice.', s: 'The disc represents the sun setting below the horizon and the icebergs.' },
  PRI: { f: 'Five red and white stripes with a blue triangle at the hoist containing a white star.', t: 'Cuba reversed: red stripes and a blue triangle.' },
  HKG: { f: 'Red field with a white five-petal bauhinia flower, each petal holding a small red star.', t: 'A white orchid-tree flower on red.' },
  MAC: { f: 'Green field with a white lotus flower over a bridge and water, under an arc of five yellow stars.', t: 'A lotus flower on green.' },
  FRO: { f: 'White field with a red Scandinavian cross outlined in blue.', t: 'Nordic cross: red with blue edges on white.' },
  BMU: { f: 'Red ensign with the Union Jack and a shield showing a lion holding a shipwreck scene.', t: 'A red British ensign with a lion shield.' },
  CYM: { f: 'Blue ensign with the Union Jack and a coat of arms with a turtle and pineapple.', t: 'A turtle on a blue British ensign.' },
  GIB: { f: 'White over red with a red three-towered castle and a golden key hanging below.', t: 'A castle and a key.' },
  ABW: { f: 'Light-blue field with two thin yellow stripes near the bottom and a red four-pointed star edged in white.', t: 'Two yellow stripes and a four-pointed star.' },
  CUW: { f: 'Blue field with a yellow horizontal stripe below the middle and two white stars in the top-left.', t: 'Blue with a yellow line and two stars.' },
  PYF: { f: 'Red, wide white, red horizontal stripes with a canoe emblem over a sun in the centre.', t: 'A canoe in front of a sun.' },
  GUM: { f: 'Dark-blue field with a red border and a pointed oval seal showing a palm tree and a canoe.', t: 'A red-bordered blue flag with a seed-shaped seal.' },
  COK: { f: 'Blue ensign with the Union Jack and a circle of fifteen white stars.', t: 'A ring of 15 white stars: 15 islands.' },
  NIU: { f: 'Yellow field with the Union Jack in the canton, holding a blue disc with a yellow star and four small stars.', t: 'A yellow flag with a Union Jack.' },
  IMN: { f: 'Red field with a triskelion of three armoured legs.', t: 'Three legs running in a circle.' },
  ALA: { f: 'Blue field with a red Scandinavian cross outlined in yellow.', t: 'Sweden\'s colours with a red cross inside.' },
  FLK: { f: 'Blue ensign with the Union Jack and a shield with a sheep and a ship.', t: 'A sheep on a blue British ensign.' },
  ESH: { f: 'Black, white and green horizontal stripes with a red triangle at the hoist and a red crescent and star in the white.', t: 'Palestine-like with a red crescent and star.' },
  ENG: { f: 'White field with a red cross (St George\'s Cross).', t: 'Red cross on white.' },
  SCO: { f: 'Blue field with a white diagonal cross (the Saltire).', t: 'White X on blue.' },
  WLS: { f: 'White over green halves with a red dragon.', t: 'The red dragon.' },
};
